window.__finlexDocLoaded(10166,{"id":10166,"articles":[{"id":1000695,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Requires an Engagement Quality Review (EQR) and concurring approval of issuance for EVERY issuer audit and interim review conducted under PCAOB standards.","seq":0},{"id":1000696,"no":"AS 1220.03–.18","heading":"Mandatory EQR, 2-Year Cooling-Off & Concurring Approval","text":"• Mandatory Scope: Required for ALL issuer audits, ICFR audits, and interim financial statement reviews.\n• Objectivity & Cooling-Off (AS 1220.08): Engagement partner cannot serve as EQR for at least 2 subsequent annual audits.\n• Concurring Approval (AS 1220.12): Firm may NOT grant permission to use the audit report until the EQR provides concurring approval of issuance.","seq":1},{"id":1000697,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Parallel to ISQM 2 (which requires EQR for listed entities and specified high-risk engagements), whereas AS 1220 mandates EQR for 100% of PCAOB issuer engagements.","seq":2},{"id":1000698,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (PCAOB Auditing Standards): https://pcaobus.org/oversight/standards/auditing-standards\nStatus: in_force.","seq":3}]});
